/// The package's own Unicode simple case folding, so that case-insensitive
/// ids, sibling order, and searches are identical on every platform.
///
/// `String.toLowerCase` cannot provide that: the VM and JavaScript use
/// different Unicode tables (JavaScript's follow the engine's ICU version),
/// and JavaScript applies the context-dependent final-sigma rule to whole
/// strings. The table in `case_folding_table.dart` is generated by
/// `tool/generate_case_folding.dart` from CaseFolding.txt of a pinned
/// Unicode version.
library;

import 'dart:typed_data';

import 'package:meta/meta.dart';

part 'case_folding_table.dart';

/// The Unicode version of the case folding table, such as `18.0.0`.
@internal
const String caseFoldingUnicodeVersion = _unicodeVersion;

/// The Unicode simple case folding of [codePoint]: its C or S mapping in
/// CaseFolding.txt, or [codePoint] itself when it has none.
///
/// Folding is idempotent (`foldCodePoint(foldCodePoint(c)) ==
/// foldCodePoint(c)`), never maps a code point to an ASCII digit or to `/`,
/// and keeps the UTF-16 length of every code point except U+1DF95, which
/// folds from two code units to one (`ß`). Surrogate code points and values
/// outside the Unicode range map to themselves. ASCII takes no table
/// lookup; other code points take a binary search over about 220 ranges.
@internal
int foldCodePoint(int codePoint) {
  if (codePoint < 0x80) {
    return codePoint >= 0x41 && codePoint <= 0x5A
        ? codePoint + 0x20
        : codePoint;
  }
  if (codePoint < _firstNonAscii || codePoint > _lastSource) return codePoint;
  // Binary search for the last range that starts at or before the code
  // point; ranges are disjoint, so only that one can contain it.
  var low = 0;
  var high = _ranges.length ~/ _rangeWidth - 1;
  while (low < high) {
    final middle = (low + high + 1) >> 1;
    if (_ranges[middle * _rangeWidth] <= codePoint) {
      low = middle;
    } else {
      high = middle - 1;
    }
  }
  final range = low * _rangeWidth;
  final start = _ranges[range];
  if (codePoint > _ranges[range + 1] ||
      (codePoint - start) % _ranges[range + 2] != 0) {
    return codePoint;
  }
  return codePoint + _ranges[range + 3];
}

/// [text] with every code point replaced by its [foldCodePoint].
///
/// Use it for every case-insensitive comparison in the package, so results
/// never depend on the platform. Surrogate pairs are decoded and folded as
/// one code point; an unpaired surrogate stays as it is. Folding works per
/// code point and never looks at the neighbours, so folding the parts of a
/// string and joining them equals folding the whole string.
///
/// Returns [text] itself when nothing changes. The result has the same
/// length as [text] unless [text] contains U+1DF95, which folds from two
/// code units to one; it is never longer. ASCII text costs one scan plus,
/// when it has a capital letter, one native lowercasing.
@internal
String foldCase(String text) {
  final length = text.length;
  var hasCapital = false;
  for (var i = 0; i < length; i++) {
    final unit = text.codeUnitAt(i);
    if (unit >= 0x80) return _foldNonAscii(text);
    if (unit >= 0x41 && unit <= 0x5A) hasCapital = true;
  }
  // For ASCII-only text every platform's toLowerCase maps exactly A-Z to
  // a-z, which is the simple case folding of ASCII; it is the fastest way
  // to build the copy.
  return hasCapital ? text.toLowerCase() : text;
}

/// [foldCase] for [text] that contains a non-ASCII code unit.
String _foldNonAscii(String text) {
  final length = text.length;
  // Allocated at the first code point that changes; until then the result
  // is [text] itself. Folding never lengthens text, so [length] suffices.
  Uint16List? units;
  var out = 0;
  var i = 0;
  while (i < length) {
    var codePoint = text.codeUnitAt(i);
    var width = 1;
    if (codePoint & 0xFC00 == 0xD800 && i + 1 < length) {
      final low = text.codeUnitAt(i + 1);
      if (low & 0xFC00 == 0xDC00) {
        codePoint = 0x10000 + ((codePoint - 0xD800) << 10) + (low - 0xDC00);
        width = 2;
      }
    }
    final folded = foldCodePoint(codePoint);
    if (units == null && folded != codePoint) {
      units = Uint16List(length);
      for (var k = 0; k < i; k++) {
        units[k] = text.codeUnitAt(k);
      }
      out = i;
    }
    if (units != null) {
      if (folded > 0xFFFF) {
        final offset = folded - 0x10000;
        units[out++] = 0xD800 + (offset >> 10);
        units[out++] = 0xDC00 + (offset & 0x3FF);
      } else {
        units[out++] = folded;
      }
    }
    i += width;
  }
  if (units == null) return text;
  return String.fromCharCodes(units, 0, out);
}
